    writer.Write(System.Text.Encoding.ASCII.GetBytes($"P6\n{width} {height}\n255\n"));
    for (int i = 0; i < rgba.Length; i += 4)
    {
        writer.Write(rgba[i]); writer.Write(rgba[i + 1]); writer.Write(rgba[i + 2]);
    }
