        // 公園 (緑の角丸)
        Vector2 park = T(40, 215);
        s.FillRoundedRect(Color2D.Rgba(180, 215, 160), park.X, park.Y, 150 * z, 120 * z, 18 * z);
        // 街区 (灰色の矩形グリッド)
