        await d.Key(Key.D, ctrl: true);                                    // "foo" を選択
        await d.Key(Key.D, ctrl: true);                                    // 2 つ目
        await d.Key(Key.D, ctrl: true);                                    // 3 つ目
        await d.Expect(() => ed.CursorCount == 3, "Ctrl+D×3 で 3 箇所選択");
        await d.Snap("selected");
