using Luxel.Graphics;
using Luxel.Graphics.WebGPU;
using LuxelWebGpuHeadless;

try
{
    using var device = new GpuDevice(WebGpuBackend.Create());
    Console.WriteLine(HeadlessWebGpuSample.Run(device).Summary);
